const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const text = JSON.stringify(payload).toLowerCase();

// Zero-Trust Non-PHI Check: Reject immediately if clinical PHI terms or patient demographics are present
const phiKeywords = ['prescription', 'diagnosis', 'symptom', 'treatment plan', 'blood test', 'biopsy', 'radiology', 'mri scan', 'ehr record', 'patient record', 'hiv', 'oncology', 'doctor notes', 'vitals', 'clinical_notes', 'patient_name', 'patientid', 'mrn', 'dob', 'birth_date', 'aadhaar', 'ssn', 'icd10', 'rx', 'lab_result'];
const containsPhi = phiKeywords.some(keyword => text.includes(keyword));

const tenantId = String(payload.tenantId || payload.tenant_id || payload.organizationId || '').trim();
const facilityId = String(payload.facilityId || payload.facility_id || '').trim();
const auditPeriod = String(payload.auditPeriod || payload.period || '2026-M10').trim();
const rlsEnforced = Boolean(payload.rlsEnforced !== undefined ? payload.rlsEnforced : true);
const rlsViolationsCount = Number(payload.rlsViolationsCount || payload.rlsViolations || 0);
const unauthorizedAccessAttempts = Number(payload.unauthorizedAccessAttempts || payload.unauthorizedAttempts || 0);
const tlsVersionEnforced = String(payload.tlsVersionEnforced || payload.tlsVersion || 'TLS 1.3').trim();
const encryptionAtRestVerified = Boolean(payload.encryptionAtRestVerified !== undefined ? payload.encryptionAtRestVerified : true);
const logIntegrityChecksum = String(payload.logIntegrityChecksum || payload.checksum || 'sha256-verified-tamper-proof').trim();
const dpdpConsentRecordsCount = Number(payload.dpdpConsentRecordsCount || payload.consentRecords || 0);

const isCompliant = Boolean(rlsEnforced && rlsViolationsCount === 0 && unauthorizedAccessAttempts === 0 && encryptionAtRestVerified && !containsPhi);
const isValidAudit = Boolean(tenantId && facilityId && !containsPhi);

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    containsPhi,
    isValidAudit,
    isCompliant,
    audit: {
      tenantId,
      facilityId,
      auditPeriod,
      rlsEnforced,
      rlsViolationsCount,
      unauthorizedAccessAttempts,
      tlsVersionEnforced,
      encryptionAtRestVerified,
      logIntegrityChecksum,
      dpdpConsentRecordsCount,
      complianceStandard: 'HIPAA Security Rule (45 CFR Part 164) & DPDP Act 2023',
      timestamp: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const item = $input.first().json;
const aud = item.audit;
const cleanTenant = aud.tenantId.replace(/[^a-zA-Z0-9]/g, '').substring(0, 10).toUpperCase();
const certId = `CERT-HLT-${cleanTenant}-${Math.floor(Date.now() / 1000)}`;

const digestData = `${certId}:${aud.tenantId}:${aud.facilityId}:${aud.auditPeriod}:${aud.logIntegrityChecksum}`;
const verificationHash = crypto.createHash('sha256').update(digestData).digest('hex');

const certificateDigest = {
  certificateId: certId,
  tenantId: aud.tenantId,
  facilityId: aud.facilityId,
  auditPeriod: aud.auditPeriod,
  status: 'AUDIT_PASSED_COMPLIANT',
  rlsStatus: 'Row-Level Security 100% Enforced; Zero Breaches',
  accessControlStatus: 'Zero Unauthorized Queries Detected',
  encryptionStatus: 'TLS 1.3 in Transit & AES-256 at Rest Verified',
  dpdpConsentIntegrity: `${aud.dpdpConsentRecordsCount} Immutable Consent Records Reconciled`,
  tamperProofChecksum: aud.logIntegrityChecksum,
  verificationHash,
  leadAuditor: 'Vikash Saravanan (Healthcare Security & Compliance Lead)',
  certifiedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'compliance_audit_passed',
    detail: {
      certificateId: certId,
      tenantId: aud.tenantId,
      facilityId: aud.facilityId,
      certificateDigest,
      auditedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const aud = item.audit || {};
const incidentTitle = item.containsPhi
  ? 'CRITICAL SECURITY BREACH: Prohibited PHI Detected in Audit Stream'
  : `COMPLIANCE VIOLATION: Healthcare Tenant ${aud.tenantId || 'Unknown'} Failed Security Audit`;

const incidentDetails = {
  incidentTitle,
  tenantId: aud.tenantId,
  facilityId: aud.facilityId,
  violations: {
    containsPhi: item.containsPhi,
    rlsViolationsCount: aud.rlsViolationsCount,
    unauthorizedAccessAttempts: aud.unauthorizedAccessAttempts,
    encryptionAtRestVerified: aud.encryptionAtRestVerified
  },
  escalatedTo: 'Vikash Saravanan (Healthcare Security Lead) & Corporate Data Protection Officer',
  actionRequired: 'Immediate database connection freeze & root-cause forensic audit initiation.',
  runbookRef: 'docs/automation/HEALTHCARE_BOUNDARIES.md'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'compliance_audit_failed',
    detail: {
      error: item.containsPhi
        ? 'CRITICAL_SECURITY_BREACH: Prohibited PHI detected in compliance audit payload'
        : 'Healthcare security compliance verification failed: RLS violations or unauthorized access attempts detected',
      incidentDetails,
      escalatedAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
